#include <bits/stdc++.h>
using namespace std;

struct Edge {
    long long distanceSquared;
    int a, b; // a == -1 denotes an edge from the palace to b
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<pair<int, int>> tents(N);
    for (auto &[x, y] : tents) cin >> x >> y;

    vector<Edge> edges;
    edges.reserve(N * (N - 1) / 2 + N);

    for (int i = 0; i < N; ++i) {
        long long x = tents[i].first;
        long long y = tents[i].second;
        edges.push_back({x * x + y * y, -1, i});

        for (int j = 0; j < i; ++j) {
            long long dx = x - tents[j].first;
            long long dy = y - tents[j].second;
            edges.push_back({dx * dx + dy * dy, j, i});
        }
    }

    sort(edges.begin(), edges.end(), [](const Edge &x, const Edge &y) {
        return x.distanceSquared > y.distanceSquared;
    });

    vector<int> best(N, -1), candidate(N, -1), touched;
    int answer = 1;

    for (size_t i = 0; i < edges.size();) {
        size_t j = i;
        while (j < edges.size() &&
               edges[j].distanceSquared == edges[i].distanceSquared) {
            const auto &[distanceSquared, a, b] = edges[j];

            if (a == -1) {
                if (candidate[b] == -1) touched.push_back(b);
                candidate[b] = max(candidate[b], 1);
            } else {
                if (best[a] >= 0) {
                    if (candidate[b] == -1) touched.push_back(b);
                    candidate[b] = max(candidate[b], best[a] + 1);
                }
                if (best[b] >= 0) {
                    if (candidate[a] == -1) touched.push_back(a);
                    candidate[a] = max(candidate[a], best[b] + 1);
                }
            }
            ++j;
        }

        for (int v : touched) {
            best[v] = max(best[v], candidate[v]);
            answer = max(answer, candidate[v]);
            candidate[v] = -1;
        }
        touched.clear();
        i = j;
    }

    cout << answer << '\n';
    return 0;
}
